pipeline {
    agent any

    environment {
        REMOTE_HOST = '20.48.1.131' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key' // Jenkins中保存的远程服务器SSH凭证ID
        REMOTE_ADDRESS = '/data/web/data-filling-mobile/'  //远程服务器web文件地址
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: '${GIALAB_ADDRESS}/front/ybt/data-filling-mobile.git ']])
            }
        }

        stage('Npm Install') {
            steps {
                //  nvm("v20.13.1") {
                    sh 'node -v'
                    sh 'pnpm install --no-frozen-lockfile'
                // }
            }
        }

        // stage('SonarQube Analysis') {
