        //                   -Dsonar.skip=true
        //             """
        //         }
        //     }
        // }

        stage('Npm Build') {
            steps {
                // sh 'npm run build'
                // nvm("v20.13.1") {
                    sh 'pnpm run build:test'
                // }
                // 或者 sh "yarn build:dev"
            }
        }


        stage('Deploy to Remote') {
            steps {
                script {
                    sh 'pwd'  
                    sh 'tar -czvf dist.tar.gz dist'
                    sh 'scp dist.tar.gz  root@${REMOTE_HOST}:${REMOTE_ADDRESS} ' 

                    sshagent([REMOTE_CREDENTIALS_ID]) {
                            sh """
                                ssh ${REMOTE_USER}@${REMOTE_HOST} '

                                cd ${REMOTE_ADDRESS}  &&

                                rm -rf dist &&

                                tar -zxvf dist.tar.gz &&

                                rm -f dist.tar.gz
                                '
                               """
                        }
                }
            }
        }
    }
}
